<?php if(!$record): ?><header class="workspace-heading"><div><h1>Solicitud no disponible</h1></div><a class="site-button button-outline" href="<?= $e($listUrl) ?>">Volver a solicitudes</a></header><?php foreach($errors as $error): ?><p class="form-errors" role="alert"><?= $e($error) ?></p><?php endforeach; ?><?php else:
    $detailUrl=$base.'/solicitudes-demo.php?'.http_build_query(array_merge($context,['request'=>(int)$record['id']]));
    $seen=array_column($history,'status');$phases=commercialDemoPhases($record['status']);
?>
<h1 class="visually-hidden">Solicitud #<?= (int)$record['id'] ?></h1>
<?php foreach($errors as $error): ?><p class="form-errors" role="alert"><?= $e($error) ?></p><?php endforeach; ?><?php if(($_GET['saved']??'')==='1'&&$method==='GET'): ?><p class="form-success" role="status">Seguimiento guardado.</p><?php endif; ?>
<?php if(http_response_code()===409): ?><p class="admin-conflict-notice">Tus cambios se conservan abajo. Revisa la información actual antes de volver a guardar. <a class="site-text-link" href="<?= $e($detailUrl) ?>">Recargar ficha</a></p><?php endif; ?>
<article class="workspace-section request-detail admin-request-detail"><ol class="request-phases" style="--request-phase-count: <?= count($phases) ?>" aria-label="Fases de la solicitud"><?php foreach($phases as $key=>$label): ?><li class="<?= $record['status']===$key?'phase-current':(in_array($key,$seen,true)?'phase-recorded':'') ?>" <?= $record['status']===$key?'aria-current="step"':'' ?>><span><?= kontaIcon(in_array($key,$seen,true)?'check':'closing') ?></span><strong><?= $e($label) ?></strong></li><?php endforeach; ?></ol>
<form class="lead-editor admin-request-form" method="post" action="<?= $e($detailUrl) ?>"><input type="hidden" name="csrf" value="<?= $e($_SESSION['auth_csrf']) ?>"><input type="hidden" name="id" value="<?= (int)$record['id'] ?>"><input type="hidden" name="version" value="<?= $e($edit['version']) ?>"><input type="hidden" name="active_tab" value="<?= $tab ?>">
<div class="admin-request-tools"><input type="hidden" name="status" value="<?= $e($record['status']) ?>"><div class="admin-quick-actions"><?php if($record['status']!=='approved'): ?><button class="site-button" type="submit" name="action" value="approve" <?= http_response_code()===409?'disabled':'' ?>>Aprobar demo</button><?php endif; ?></div></div>
<nav class="request-detail-tabs" aria-label="Secciones de la solicitud"><?php foreach(['datos'=>'Datos','seguimiento'=>'Seguimiento','notas'=>'Notas internas'] as $key=>$label): ?><a href="<?= $e($detailUrl.'&tab='.$key) ?>" data-request-tab="<?= $key ?>" <?= $tab===$key?'aria-current="page"':'' ?>><?= $label ?></a><?php endforeach; ?></nav>
<section id="request-tab-datos" class="request-detail-panel" data-request-panel="datos" <?= $tab!=='datos'?'hidden':'' ?>><h2>Datos de la solicitud</h2><dl class="request-detail-fields"><div><dt>Nombre</dt><dd><?= $e($record['full_name']) ?></dd></div><div><dt>Empresa o nombre personal</dt><dd><?= $e($record['business_name']) ?></dd></div><div><dt>Correo electrónico</dt><dd><a href="mailto:<?= $e($record['email']) ?>"><?= $e($record['email']) ?></a></dd></div><div><dt>Teléfono</dt><dd><a href="tel:<?= $e(preg_replace('/[^0-9+]/','',$record['phone'])) ?>"><?= $e($record['phone']) ?></a></dd></div><div><dt>Tipo de negocio</dt><dd><?= $e($sectors[$record['sector']]??$record['sector']) ?></dd></div><div><dt>Ciudad</dt><dd><?= $e($record['city']?:'No indicada') ?></dd></div><div><dt>Empresas / usuarios</dt><dd><?= $e($record['company_count'].' / '.$record['user_count']) ?></dd></div><div><dt>Plan de interés</dt><dd><?= $e($plans[$record['plan_key']]['name']??'Necesita orientación') ?></dd></div><div><dt>Contacto preferido</dt><dd><?= $e(['email'=>'Correo electrónico','phone'=>'Llamada','whatsapp'=>'WhatsApp'][$record['contact_method']]??'') ?></dd></div><div><dt>Solicitud / consentimiento</dt><dd><?= $e($record['created_at']) ?><small>Contacto autorizado: <?= $e($record['consented_at']) ?></small></dd></div></dl><div class="request-detail-needs"><h3>Lo que necesita resolver</h3><p><?= $e($record['requirements']?:'No se indicaron necesidades adicionales.') ?></p></div></section>
<section id="request-tab-seguimiento" class="request-detail-panel" data-request-panel="seguimiento" <?= $tab!=='seguimiento'?'hidden':'' ?>><h2>Seguimiento y respuesta</h2><h3 class="admin-history-title">Historial compartido con el cliente</h3><ol class="portal-timeline"><?php foreach($history as $event): ?><li><span class="workspace-event-mark"><?= kontaIcon('check') ?></span><div class="workspace-event"><header><strong><?= $e($statuses[$event['status']]??$event['status']) ?></strong><time><?= $e($event['created_at']) ?></time></header><?php if($event['message']!==''): ?><p><?= $e($event['message']) ?></p><?php endif; ?></div></li><?php endforeach; ?></ol><?php if(!$history): ?><p class="request-detail-description">Todavía no hay actualizaciones compartidas.</p><?php endif; ?></section>
<section id="request-tab-notas" class="request-detail-panel" data-request-panel="notas" <?= $tab!=='notas'?'hidden':'' ?>><h2>Notas internas</h2><label class="admin-response-label">Observaciones privadas<textarea name="internal_notes" maxlength="2000" rows="6"><?= $e($edit['internal_notes']) ?></textarea></label></section>
<footer class="admin-request-actions"><?php if($record['status']!=='rejected'): ?><button class="site-button button-outline admin-reject-button" type="submit" name="action" value="reject" <?= http_response_code()===409?'disabled':'' ?>>Rechazar demo</button><?php endif; ?><a class="site-button button-outline" href="<?= $e($listUrl) ?>">Volver al listado</a><button class="site-button button-outline" type="submit" name="action" value="save" <?= http_response_code()===409?'disabled':'' ?>>Guardar cambios</button></footer></form></article>
<?php endif; ?>
